import React, { useEffect, useState } from 'react'
import "./logout.css"
import Button from '../../../../components/ui/Button'
import { useDispatch, useSelector } from 'react-redux'
import { logoutAction } from '../../actions/authAction'
import logoutIcon from "./logoutIcon.svg"
import { NavLink, useNavigate } from 'react-router-dom'
import Loader from '../../../../components/loader/Loader'
import { getCurrentUser } from '../../../../libs/getCurrentUser'
import { getAuthError, getauthStatus, setErrorStatus, updateAuthStatus } from '../../reducers/authSlice'
import ConfirmationModal from '../../../../components/confirmationModal/ConfirmationModal'
import { useWindowWidth } from '../../../landing'

const Logout = ({show}) => {
  const [showConfirmationModal, setshowConfirmationModal] = useState(false)
    const authStatus = useSelector(getauthStatus)
    const errorStatus = useSelector(getAuthError)
    const {screenWidth} = useWindowWidth()
    const isDesktop = screenWidth >= 1306

    const dispatch = useDispatch()
    const navigate = useNavigate()
    const currentUser = getCurrentUser();

    const logUserOut = async () => {
      try{
        const payload = {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${currentUser.userToken}
            `,
          },
        };
        dispatch(logoutAction(payload))
      }
      catch(error){
        console.log(error)
      }
      finally{
        dispatch(setErrorStatus(null))
      }
    }

    useEffect(() => {
      if(authStatus === "fulfilled" && !currentUser.userName){
        navigate("/login")
      }
    }, [authStatus])

    const style = {
      positon: "fixed",
      top: "0",
      left: "0",
      right: "0",
      bottom: "0"
    }

    if(authStatus === "loading"){
      return <Loader text={"Logging out"} style={style} />
    }

    if(errorStatus && authStatus === "failed"){
      alert(errorStatus)
      dispatch(updateAuthStatus("idle"))
    }

  return (
    <div className="logout-container">
      {showConfirmationModal && <ConfirmationModal ariaLabel={"Click to logout from Ventmoir"} onConfirm={logUserOut} onCancel={() => setshowConfirmationModal(false)} heading={"Are you sure you want to logout?"} />}
      <Button
        handleEvent={(e) => {
          e.stopPropagation()
          setshowConfirmationModal(true)}}
        keyDownEvent={logUserOut}
        ariaLabel={"Click to open logout confirmation modal"}
        text={
          <>
            <NavLink>
              <img src={logoutIcon}  aria-hidden="true" alt="Logout icon" />
              {show ? <p className="slide-in">Logout</p> : isDesktop  &&  <p className="slide-in">Logout</p>}
            </NavLink>
          </>
        }
      />
    </div>
  )
}

export default Logout
