import { createSlice, createEntityAdapter } from "@reduxjs/toolkit";
import { getPostsByUser } from "../../user/actions/getPostsByUser";

const userPostAdapter = createEntityAdapter({
  selectId: (entity) => entity._id,
  sortComparer: (a, b) => b._id.localeCompare(a._id), // Sort by post ID in descending order
});
const initialState = userPostAdapter.getInitialState({
  status: "idle",
  error: null,
});

const userPostSlice = createSlice({
  name: "userPost",
  initialState,
  reducers: {
    updateUserPostStatus(state, action) {
      state.status = action.payload;
    },
    setUserPostErrorMessage(state, action) {
      state.error = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(getPostsByUser.pending, (state, action) => {
        state.status = "loading";
      })
      .addCase(getPostsByUser.fulfilled, (state, action) => {
        state.status = "fulfilled";
        userPostAdapter.upsertMany(state, action.payload);
      })
      .addCase(getPostsByUser.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

export const { selectAll: selectAllUserPost } = userPostAdapter.getSelectors(
  (state) => state.userPost
);

export const getUserPostStatus = (state) => state.userPost.status;
export const getUserPostErrorMessage = (state) => state.userPost.error;
export default userPostSlice.reducer;
