import { createSlice, createEntityAdapter } from "@reduxjs/toolkit";
import { updateBio } from "../../bio/actions/updateBio";

const profileSettingAdapater = createEntityAdapter({});
const initialState = profileSettingAdapater.getInitialState({
  status: "idle",
  error: null,
});

const profileSettingSlice = createSlice({
  name: "profileSetting",
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(updateBio.pending, (state, action) => {
        state.status = "loading";
      })
      .addCase(updateBio.fulfilled, (state, action) => {
        state.status = "fulfilled";
      })
      .addCase(updateBio.rejected, (state, action) => {
        state.status = "failed";
        state.error = action.error.message;
      });
  },
});

export const {
  selectAll: selectAll,
  selectById,
  selectIds,
} = profileSettingAdapater.getSelectors((state) => state.profileSettingSlice);

export const getUpdateBioStatus = (state) => state.profileSetting.status;
export default profileSettingSlice.reducer;

